INSERT INTO lib_rule (id,category,data,catalog_entry_id,catalog_kind) VALUES (1,'General','{"id":"ability-check","name":"Ability Check","category":"General","related":["d20-test"],"text":"An ability check is a [[d20-test|D20 Test]] that represents using one of the six abilities—or a specific skill associated with an ability—to overcome a challenge. *See also* \"Playing the Game\" (\"D20 Tests\" and \"Proficiency\").","url":"https://www.dndbeyond.com/sources/dnd/br-2024/rules-glossary#AbilityCheck"}',19,'rule');
