INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (1,'dexterity','{"id": "skill-acrobatics", "name": "Acrobatics", "kind": "Dexterity skill", "icon": "assets/skills/acrobatics.svg", "matchCase": true, "body": "Staying on your feet where footing is treacherous — a rain-slick deck, a\ntightrope, a patch of ice — and tumbling, flipping, or diving out of\nharm''s way.\n"}',20,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (2,'wisdom','{"id": "skill-animal-handling", "name": "Animal Handling", "kind": "Wisdom skill", "icon": "assets/skills/animal-handling.svg", "matchCase": true, "body": "Calming a spooked animal, reading its intentions, or coaxing it into\ndoing something it would rather not. Also covers controlling a mount in\na difficult manoeuvre.\n"}',21,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (3,'intelligence','{"id": "skill-arcana", "name": "Arcana", "kind": "Intelligence skill", "icon": "assets/skills/arcana.svg", "matchCase": true, "body": "Recalling lore about spells, magic items, eldritch symbols, magical\ntraditions, and the planes of existence — and identifying a spell as it\nis being cast.\n"}',22,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (4,'strength','{"id": "skill-athletics", "name": "Athletics", "kind": "Strength skill", "icon": "assets/skills/athletics.svg", "matchCase": true, "body": "Climbing, jumping, and swimming when circumstances make them hard, plus\ncontests of raw physical force: grappling, shoving, and breaking free of\na grapple.\n"}',23,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (5,'charisma','{"id": "skill-deception", "name": "Deception", "kind": "Charisma skill", "icon": "assets/skills/deception.svg", "matchCase": true, "body": "Convincingly saying what is not true — a bluff, a false identity, a\nstraight face over a con. Usually opposed by the target''s\n[[skill-insight|Insight]].\n"}',24,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (6,'intelligence','{"id": "skill-history", "name": "History", "kind": "Intelligence skill", "icon": "assets/skills/history.svg", "matchCase": true, "body": "Recalling lore about past events, legendary people, ancient kingdoms,\nwars, and the rise and fall of civilisations.\n"}',25,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (7,'wisdom','{"id": "skill-insight", "name": "Insight", "kind": "Wisdom skill", "icon": "assets/skills/insight.svg", "matchCase": true, "body": "Reading a creature''s true intentions from body language, tone, and the\nshape of what they are not saying. The usual counter to\n[[skill-deception|Deception]].\n"}',26,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (8,'charisma','{"id": "skill-intimidation", "name": "Intimidation", "kind": "Charisma skill", "icon": "assets/skills/intimidation.svg", "matchCase": true, "body": "Getting your way through threats, hostile displays, or sheer menace —\nwhether that is a drawn blade, a pointed reminder, or a very long\nsilence.\n"}',27,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (9,'intelligence','{"id": "skill-investigation", "name": "Investigation", "kind": "Intelligence skill", "icon": "assets/skills/investigation.svg", "matchCase": true, "body": "Deducing from evidence: finding the hidden catch on a puzzle box,\nworking out what a weapon did to a wound, or searching a room for what\nit is concealing. Where [[skill-perception|Perception]] is noticing,\nInvestigation is reasoning.\n"}',28,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (10,'wisdom','{"id": "skill-medicine", "name": "Medicine", "kind": "Wisdom skill", "icon": "assets/skills/medicine.svg", "matchCase": true, "body": "Diagnosing an illness, identifying a poison, determining the cause of\ndeath, or stabilising a dying creature without a healing kit.\n"}',29,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (11,'intelligence','{"id": "skill-nature", "name": "Nature", "kind": "Intelligence skill", "icon": "assets/skills/nature.svg", "matchCase": true, "body": "Recalling lore about terrain, plants and animals, weather, seasons, and\nthe natural cycles of the world.\n"}',30,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (12,'wisdom','{"id": "skill-perception", "name": "Perception", "kind": "Wisdom skill", "icon": "assets/skills/perception.svg", "matchCase": true, "body": "Noticing what is there to be noticed — a hidden creature, a sound behind\na door, a change in the light. Your Passive Perception is what you spot\nwithout looking, and it is what hiding creatures are measured against.\n"}',31,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (13,'charisma','{"id": "skill-performance", "name": "Performance", "kind": "Charisma skill", "icon": "assets/skills/performance.svg", "matchCase": true, "body": "Holding an audience: music, dance, acting, storytelling, or any other\nentertainment that asks people to watch you and be pleased.\n"}',32,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (14,'charisma','{"id": "skill-persuasion", "name": "Persuasion", "kind": "Charisma skill", "icon": "assets/skills/persuasion.svg", "matchCase": true, "body": "Influencing someone with tact, grace, and good faith — negotiating a\ntruce, winning a favour, or convincing a crowd. The honest counterpart\nto [[skill-deception|Deception]].\n"}',33,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (15,'intelligence','{"id": "skill-religion", "name": "Religion", "kind": "Intelligence skill", "icon": "assets/skills/religion.svg", "matchCase": true, "body": "Recalling lore about deities, rites and prayers, religious hierarchies,\nholy symbols, and the practices of cults.\n"}',34,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (16,'dexterity','{"id": "skill-sleight-of-hand", "name": "Sleight of Hand", "kind": "Dexterity skill", "icon": "assets/skills/sleight-of-hand.svg", "matchCase": true, "body": "Manual trickery: picking a pocket, planting something on a person,\nconcealing an object on your body, or palming a coin in plain sight.\n"}',35,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (17,'dexterity','{"id": "skill-stealth", "name": "Stealth", "kind": "Dexterity skill", "icon": "assets/skills/stealth.svg", "matchCase": true, "body": "Moving unseen and unheard — slipping past guards, staying behind cover,\nand hiding. Measured against the Passive\n[[skill-perception|Perception]] of whoever might spot you.\n"}',36,'skill');
INSERT INTO lib_skill (id,ability,data,catalog_entry_id,catalog_kind) VALUES (18,'wisdom','{"id": "skill-survival", "name": "Survival", "kind": "Wisdom skill", "icon": "assets/skills/survival.svg", "matchCase": true, "body": "Living off the land and reading it: following tracks, hunting and\nforaging, navigating wilderness, predicting weather, and avoiding\nnatural hazards such as quicksand.\n"}',37,'skill');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (1,'{"id": "ammunition", "name": "Ammunition", "text": "You can use a weapon that has the Ammunition property to make a ranged attack only if you have ammunition to fire from it. The type of ammunition required is specified with the weapon''s range. Each attack expends one piece of ammunition. Drawing the ammunition is part of the attack (you need a free hand to load a one-handed weapon). After a fight, you can spend 1 minute to recover half the ammunition (round down) you used in the fight; the rest is lost."}',38,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (2,'{"id": "finesse", "name": "Finesse", "text": "When making an attack with a Finesse weapon, use your choice of your Strength or Dexterity modifier for the attack and damage rolls. You must use the same modifier for both rolls."}',39,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (3,'{"id": "heavy", "name": "Heavy", "text": "You have Disadvantage on attack rolls with a Heavy weapon if it''s a Melee weapon and your Strength score isn''t at least 13 or if it''s a Ranged weapon and your Dexterity score isn''t at least 13."}',40,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (4,'{"id": "light", "name": "Light", "text": "When you take the Attack action on your turn and attack with a Light weapon, you can make one extra attack as a Bonus Action later on the same turn. That extra attack must be made with a different Light weapon, and you don''t add your ability modifier to the extra attack''s damage unless that modifier is negative. For example, you can attack with a Shortsword in one hand and a Dagger in the other using the Attack action and a Bonus Action, but you don''t add your Strength or Dexterity modifier to the damage roll of the Bonus Action unless that modifier is negative."}',41,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (5,'{"id": "loading", "name": "Loading", "text": "You can fire only one piece of ammunition from a Loading weapon when you use an action, a Bonus Action, or a Reaction to fire it, regardless of the number of attacks you can normally make."}',42,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (6,'{"id": "range", "name": "Range", "text": "A Range weapon has a range in parentheses after the Ammunition or Thrown property. The range lists two numbers. The first is the weapon''s normal range in feet, and the second is the weapon''s long range. When attacking a target beyond normal range, you have Disadvantage on the attack roll. You can''t attack a target beyond the long range."}',43,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (7,'{"id": "reach", "name": "Reach", "text": "A Reach weapon adds 5 feet (1.5 m) to your reach when you attack with it, as well as when determining your reach for Opportunity Attacks with it."}',44,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (8,'{"id": "thrown", "name": "Thrown", "text": "If a weapon has the Thrown property, you can throw the weapon to make a ranged attack, and you can draw that weapon as part of the attack. If the weapon is a Melee weapon, use the same ability modifier for the attack and damage rolls that you use for a melee attack with that weapon."}',45,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (9,'{"id": "two-handed", "name": "Two-Handed", "text": "A Two-Handed weapon requires two hands when you attack with it."}',46,'weapon_property');
INSERT INTO lib_weapon_property (id,data,catalog_entry_id,catalog_kind) VALUES (10,'{"id": "versatile", "name": "Versatile", "text": "A Versatile weapon can be used with one or two hands. A damage value in parentheses appears with the property. The weapon deals that damage when used with two hands to make a melee attack."}',47,'weapon_property');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (1,'{"id": "cleave", "name": "Cleave", "text": "If you hit a creature with a melee attack roll using this weapon, you can make a melee attack roll with the weapon against a second creature within 5 feet (1.5 m) of the first that is also within your reach. On a hit, the second creature takes the weapon''s damage, but don''t add your ability modifier to that damage unless that modifier is negative. You can make this extra attack only once per turn."}',48,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (2,'{"id": "graze", "name": "Graze", "text": "If your attack roll with this weapon misses a creature, you can deal damage to that creature equal to the ability modifier you used to make the attack roll. This damage is the same type dealt by the weapon, and the damage can be increased only by increasing the ability modifier."}',49,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (3,'{"id": "nick", "name": "Nick", "text": "When you make the extra attack of the Light property, you can make it as part of the Attack action instead of as a Bonus Action. You can make this extra attack only once per turn."}',50,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (4,'{"id": "push", "name": "Push", "text": "If you hit a creature with this weapon, you can push the creature up to 10 feet (3 m) straight away from yourself if it is Large or smaller."}',51,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (5,'{"id": "sap", "name": "Sap", "text": "If you hit a creature with this weapon, that creature has Disadvantage on its next attack roll before the start of your next turn."}',52,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (6,'{"id": "slow", "name": "Slow", "text": "If you hit a creature with this weapon and deal damage to it, you can reduce its Speed by 10 feet (3 m) until the start of your next turn. If the creature is hit more than once by weapons that have this property, the Speed reduction doesn''t exceed 10 feet (3 m)."}',53,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (7,'{"id": "topple", "name": "Topple", "text": "If you hit a creature with this weapon, you can force the creature to make a Constitution saving throw (DC 8 plus the ability modifier used to make the attack roll and your Proficiency Bonus). On a failed save, the creature has the Prone condition."}',54,'weapon_mastery');
INSERT INTO lib_weapon_mastery (id,data,catalog_entry_id,catalog_kind) VALUES (8,'{"id": "vex", "name": "Vex", "text": "If you hit a creature with this weapon and deal damage to the creature, you have Advantage on your next attack roll against that creature before the end of your next turn."}',55,'weapon_mastery');
